-- GENERATED by `wfj generate` from data/gossip/gossip-60.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["60010ac12ba06000"] = { "Interessante... la Pietra possiede un grande potenziale magico, ma in una forma del tutto grezza...", "." },
  ["600228f9cb01be05"] = { "Lo skycutter che arriva qui ti porterà dritto alla città di Dalaran.", "." },
  ["6008cd3f3eb50aa4"] = { "Spiriti dell'Acqua, vi rendo lode e vi chiedo un favore. Avete udito le suppliche di {name}, e confido che le sue intenzioni siano nobili. Vi prego, ci aiuterete?", "." },
  ["600cec5684480ff4"] = { "Lascia questo luogo sacro o muori!", "." },
  ["600df1dce5be9123"] = { "Il Grande ti schiaccerà!", "." },
  ["60167880216079d9"] = { "Elune-adore, <fratello/sorella> <mio/mia>. Qui sei <benvenuto/benvenuta>. Parla, e farò ciò che posso per aiutarti.", "." },
  ["601aa2f7f1504b36"] = { "Tutti i tipi da furfanti bazzicano la Caverna degli Inganni, a nord dei cancelli di ⟦Ironforge=Forgiardente⟧. Scommetto che ci troverai Fenthwick, di sicuro intento a contare le monete di un altro borseggiatore. Uno di questi giorni lo acchiappo!\n\nNel frattempo terrò d'occhio anche te, <ragazzo/ragazza>.", "." },
  ["601e4a2a98d50fbe"] = { "È stato raccolto tutto e lo stiamo spedendo a ⟦Silithus=Silitus⟧, {class}. L'ultima parte dovrebbe arrivare entro un giorno. Posso solo sperare che, quando il gong sarà suonato e i cancelli aperti, i nostri sforzi qui facciano la differenza e salvino molte vite.", "." },
  ["6025c5f1574ba394"] = { "Dov'è il tuo salvatore? Quanto pensi di resistere ai miei attacchi?", "." },
  ["602a5896f30eeefe"] = { "«Ottimo lavoro nel raccogliere risorse per la guerra», dicevano. «Ecco una promozione», dicevano. Quello che intendevano davvero era: «Sei di stanza davanti a un alveare di insetti a ⟦Silithus=Silitus⟧ con un branco di nani sudati, Carnes!»\n\nGrazie per la promozione, capitano!", "." },
  ["602b7ed81ed864dd"] = { "{name} conquista il Cimitero di Nevealta! Se nessuno lo contende, l'⟦Alliance=Alleanza⟧ lo controllerà!", "." },
  ["6030091b2f7c3f8f"] = { "Coboldi buoni a nulla!", "." },
  ["603427210dab9a79"] = { "Perdonami, {name}! La tua morte non fa che aggiungersi al mio fallimento!", "." },
  ["603bccf17be772dc"] = { "Miserabile {name}! I tuoi amici ti raggiungeranno presto!", "." },
  ["603e294f2182d8a3"] = { "Possiamo cominciare.", "." },
  ["604211ad0588c969"] = { "Rallegratevi per l'impresa di {name}! Esultate al suo grido di battaglia!", "." },
  ["6048201cfe702e82"] = { "Certo che commerciamo in oro! Dopotutto è una valuta universale.\r\n\nTuttavia, per gli scambi tra di noi abbiamo un sistema tutto nostro. Si chiama Merchant's Favor, e in pratica ci rende indipendenti dal valore sempre oscillante dell'oro e dell'argento. Così gli scambi tra i membri dell'Azeroth Commerce Authority restano costanti, giusti ed equi. E prima che tu lo chieda: no, non si può convertire in oro.\r\n\nUsiamo ancora l'oro per gli scambi semplici, come fili di base o fiale da alchimia, sai, i mestieri di tutti i giorni. Per il resto ci affidiamo al Merchant's Favor.\r\n\nPiù aiuterai con le nostre spedizioni perdute e con l'ondata di ordini di creazione, più Favor guadagnerai!", "." },
  ["604a347bc3b5c826"] = { "{name} UCCIDE! <Lui/Lei> uccide te ora! SCAPPA! SCAPPA!", "." },
  ["604df8d9d4037280"] = { "Voglio vedere i miei nemici, Ryson. Mostrameli.", "." },
  ["604ebac2035c954d"] = { "Ehi, tu. Puoi prendere il contenuto del mio calderone. Doveva essere la seconda fase del mio piano: abiti seducenti.", "." },
  ["60526e0b544ae8c0"] = { "Reginald... io... mi dispiace.", "." },
  ["6055c68797e6d8c0"] = { "Mi rammarica informarti che non hai superato l'esame, dottore.", "." },
  ["6058ef90ea0ce880"] = { "%s taglia e modella i tronchi in assi di legno lisce.", "." },
  ["605a441b854c0c1c"] = { "Mentre cadi in battaglia, noi diventiamo sempre più forti. L'esito è uno solo, inevitabile. Preparati alla fine!", "." },
  ["606232a0a9e04e3c"] = { "Ah, soldato Hendel. Un piacere conoscere uno degli uomini disposti a tradire il proprio regno per orgoglio.", "." },
  ["60623d1b2831038a"] = { "Ci sono!", "." },
  ["606496bc4809f0b0"] = { "John, tesoro, dove sei?", "." },
  ["607236b0b110d6d7"] = { "Ehi, <signore/signorina>. Hai l'aria di <un/una> {class} che se ne intende di vino. Ho un favore da chiederti, e credo di poterti fare un'offerta che non puoi rifiutare... fidati!", "." },
  ["6077e5e42cbfd7c3"] = { "{name}, questo è arrivato per te stamattina.", "." },
  ["607c071ee6cd2d2c"] = { "L'anziano Goldwell passa il suo tempo nel villaggio di Kharanos, a Dun Morogh.", "." },
  ["60850155e51488e4"] = { "È Erma che si occupa di tutti gli animali qui intorno. Si trova proprio fuori dalla Locanda del Fiero Leone, se hai bisogno di parlarle.", "." },
  ["608a49cdda299a5c"] = { "Presto libereremo Azeroth dalla presenza abominevole dei silitidi. Il loro potenziale distruttivo è molto più grande di quanto tu abbia visto con i tuoi occhi, {name}. Dietro le loro attività ci sono poteri più grandi e più oscuri.", "." },
  ["6091e3b178b7ed4d"] = { "%s prende la mira verso le bottiglie...", "." },
  ["60929fa05f73c8d9"] = { "La ⟦Coldtooth Mine=Miniera di Dentefreddo⟧ si trova in territorio dell'⟦Horde=Orda⟧, sulle montagne a nord del ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧.\n\nÈ controllata dall'⟦Horde=Orda⟧.", "." },
  ["60935615b096cc27"] = { "Salute, giovane {class}. È qui che il tuo Capoguerra sfidò Orgrim Doomhammer! Anche se è successo tanti anni fa, è un'immagine ancora viva nella mia mente.", "." },
  ["609c847e30ed4a5c"] = { "Posso insegnarti i segreti di ⟦Mechanostrider Piloting=Cavalca-Tecnostruzzo⟧, a patto che tu abbia abbastanza oro per pagare la lezione!", "." },
  ["60a05a906b9dad68"] = { "Chiamami «Capo». Cos'hai per me!", "." },
  ["60a6efdda2e5f877"] = { "Hai detto qualcosa, <giovanotto/signorina>? Non sento un accidente, a parte il fischio nelle orecchie. Ehi, cos'è quella roba che hai lì?", "." },
  ["60a8da6e9650954f"] = { "Ehi! Questo è molto più di quanto avessi messo in conto: da qui in poi sono fatti tuoi, Slim!", "." },
  ["60aa0093f4e0caae"] = { "%s manca il colpo...", "." },
  ["60aba2226023ceaa"] = { "Salve, {race}. Cosa posso fare per te?", "." },
  ["60af55a1861b48c4"] = { "Scommetto che per Quae sarà importante. Se ne intende parecchio di queste cose: non è un'esperta, ma se ne intende.", "." },
  ["60b9973f28c6cc09"] = { "%s comincia ad attingere energia dalla terra", "." },
  ["60be05b0bcfec47b"] = { "L'ultimo l'hai lanciato tu, idiota. Tocca a me.", "." },
  ["60c0e3cfbbac6829"] = { "Lord Staghelm, dove vai? Spezzeresti il nostro legame per orgoglio?", "." },
  ["60c341a2a290288e"] = { "Ehi, ciao, <amico/amica>. Mi chiamo Remy. Vengo da ⟦Redridge=Crestarossa⟧, a est, e sono qui in cerca di affari, in cerca di affari. Hai qualcosa... hai qualcosa??", "." },
  ["60da97c780585802"] = { "Calma, gente. Non vogliamo rivelare la nostra posizione.", "." },
  ["60def8a7b388810a"] = { "Dove stiamo combattendo il Flagello?", "." },
  ["60e561fd559ff10c"] = { "Questo è il saluto di un venditore di stoffa non morto.", "." },
  ["60f275cd21c0012d"] = { "Quando guardo una succube, il mio cuore prende il volo... Ma al tempo stesso sento quasi la mia anima rifluire, allontanarsi come la marea.\n\nStai in guardia, amico mio.", "." },
  ["60f391e4e9bed353"] = { "Cerchi il frammento di scettro affidato alla protezione dello Stormo dei Draghi Blu?\n\n<Azuregos sembra sorridere.>", "." },
  ["60fc9fc176c8299a"] = { "Mmm, il tuo lavoro è discreto, ma è ben lontano dalla qualità che cerco in un allievo. Va' a parlare con il fabbro Argus a ⟦Goldshire=Borgodoro⟧: di sicuro può insegnarti le basi. Poi, quando hai finito, torna da me e ti darò una piccola prova per assicurarmi che tu sia <pronto/pronta>.", "." },
})
